	[Tooltip("Precision of the fragment shader output.

[fixed4] 11 bit, cheap and very low precision output, range of –2 to +2 and 1/256th precision

[half4] 16 bit, range of –60000 to +60000, with about 3 decimal digits of precision

[float4] 32 bit, full floating point precision")]
	public ShapesConfig.FragOutputPrecision FRAG_OUTPUT_V4; // 0x70
	[Tooltip("[Off] Turns off local anti-aliasing

[Medium] Approximate, usually good enough. This uses the approximate partial derivative of fwidth for anti-aliasing

[High] Higher quality, mathematically correct. Primarily handles diagonals better as it uses more precise partial derivative calculations")]
	public ShapesConfig.LocalAAQuality LOCAL_ANTI_ALIASING_QUALITY; // 0x74
	[Tooltip("[Low] Direct barycentric interpolation of colors per vertex
  • super cheap
  • prone to triangular artifacts
  • playstation 1 energy

[Medium] Barycentric interpolation of UVs, bilinear interpolation in the fragment shader
  • this gets you like 80% there
  • most games settle here
  • only use quality above this if you really need to
  • or if you are as pretentious as me with colors

[High2D] 2D only, Z plane only, inverse barycentric interpolation in the fragment shader based on vertex positions.
  • mathematically correct
  • ...when restricted to the XY plane
  • numerically unstable otherwise
  • utterly and completely broken on the X plane or the Y plane. like, it goes invisible and I don't even know why. I think we're dividing by 0 or something idk

[High] Full 3D inverse barycentric interpolation in the fragment shader based on vertex positions.
  • mathematically correct method
  • ...when all points are planar
  • skew quads use a best-fit 2D projection
  • the shader gets like way more expensive but the colors are nice and you can look at it and go "nice"")]
	public ShapesConfig.QuadInterpolationQuality QUAD_INTERPOLATION_QUALITY; // 0x78
	[Tooltip("Noots is a unit, in addition to Meters and Pixels, useful for resolution-independent sizing
A noot is proportional to the shortest dimension of your resolution (note: this is unrelated to physical size)

Converting noots to pixels:
min(res.x,res.y)*(noots/NAS)
res = screen resolution
NAS = noots across screen

You can specify how big a single noot is here, though, I recommended leaving it at the default value of 100

1 = 1 noot is 100% of the screen
50 = 1 noot is 50% of the screen
100 = 1 noot is 1% of the screen (default)
(100 is like vmin in CSS)")]
	public int NOOTS_ACROSS_SCREEN; // 0x7C

